def find_inverse_permutation(n, p):
    if n != len(p):
        raise ValueError("The length of p must be equal to n")

    # Create a dictionary to map each element of p to its index
    index_map = {x: i + 1 for i, x in enumerate(p)}

    # Initialize the result list with zeros
    q = [0] * n

    # Try to construct the permutation q
    for i in range(1, n + 1):
        try:
            j = index_map[index_map[i]]
            q[j - 1] = i
        except KeyError:
            return -1

    return q

