def find_inverse_permutation(p):
    n = len(p)
    visited = [False] * (n + 1)
    result = [-1] * n

    for i in range(1, n + 1):
        if not visited[i]:
            cycle = []
            x = i
            while not visited[x]:
                visited[x] = True
                cycle.append(x)
                x = p[x - 1]

            if len(cycle) % 2 == 0:
                for j in range(len(cycle)):
                    result[cycle[j] - 1] = cycle[(j + len(cycle) // 2) % len(cycle)] - 1
            else:
                return -1

    return result

